#ifndef MATA_LAZY_GENERATOR_HH_
#define MATA_LAZY_GENERATOR_HH_

#include "mata/utils/generator-support.hh"

#include "mata/alphabet.hh"

#if MATA_HAS_GENERATOR_SUPPORT

	#include <generator>
	#include <ranges>

namespace mata::utils {

/// Support class for the bindings-facing *_lazy_ptr() functions (e.g. nfa::plumbing::get_words_lazy_ptr()).
///  Pull-based adaptor over a @c std::generator<T>, exposing @c done()/@c next() instead of C++23 range-for
///  iteration. Exists for callers that cannot drive a @c std::generator directly — namely the Python bindings,
///  generated by Cython, which has no notion of C++23 coroutines or sentinels — so they can still consume one value
///  at a time instead of materializing the whole sequence.
///
/// The generator is resumed past a value only once done() or next() asks for the one after it, never right when
///  next() takes it, so a caller that stops after k values does not pay for the search of the (k + 1)-th, which may
///  dominate (e.g. noodlify_mult_eps_lazy() may walk exponentially many routes after its last noodle). Not
///  thread-safe: done() and next() may run the generator.
template <class T> class LazyGenerator {
  public:
	/// Runs the generator to its first value.
	explicit LazyGenerator(std::generator<T> generator)
		: generator_{std::move(generator)},
		  it_{generator_.begin()},
		  holds_value_{it_ != std::default_sentinel} {}

	LazyGenerator(const LazyGenerator&) = delete;
	LazyGenerator& operator=(const LazyGenerator&) = delete;
	LazyGenerator(LazyGenerator&&) = delete;
	LazyGenerator& operator=(LazyGenerator&&) = delete;

	/// True when there are no more values to yield. Runs the generator to its next value unless one is held.
	bool done() {
		if (!holds_value_ && it_ != std::default_sentinel) {
			++it_;
			holds_value_ = it_ != std::default_sentinel;
		}
		return !holds_value_;
	}

	/// Take the next value. @pre !done().
	T next() {
		done();
		holds_value_ = false;
		return std::move(*it_);
	}

  private:
	std::generator<T> generator_;
	std::ranges::iterator_t<std::generator<T>> it_;
	/// Whether *it_ is a value not taken yet.
	bool holds_value_;
};

} // namespace mata::utils

#else // MATA_HAS_GENERATOR_SUPPORT

	#include <stdexcept>

namespace mata::utils {

/// Fallback declaration used when the standard library does not implement @c std::generator (notably Apple's system
///  libc++, even under `-std=c++23`). The type stays declared so that the bindings-facing *_lazy_ptr() functions
///  have the same signature on every platform; it is never instantiated, because those functions throw instead of
///  constructing one.
template <class T> class LazyGenerator {
  public:
	LazyGenerator(const LazyGenerator&) = delete;
	LazyGenerator& operator=(const LazyGenerator&) = delete;
	LazyGenerator(LazyGenerator&&) = delete;
	LazyGenerator& operator=(LazyGenerator&&) = delete;

	bool done() { return true; }

	T next() { throw std::runtime_error("mata was built without std::generator support"); }

  private:
	LazyGenerator() = default;
};

} // namespace mata::utils

#endif // MATA_HAS_GENERATOR_SUPPORT

namespace mata::utils {
using LazyWordGenerator = LazyGenerator<Word>;
} // namespace mata::utils

#endif // MATA_LAZY_GENERATOR_HH_
